// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address caller, uint256 initialFunding) public {
        vm.assume(initialFunding > 0);
        vm.assume(caller != address(c));
        vm.assume(caller != c.Owner());
        vm.deal(address(c), initialFunding);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        bool ok = true;
        try c.withdraw() { ok = true; } catch { ok = false; }
        if (ok) {
            assertEq(address(c).balance, 0);
        } else {
            assertEq(address(c).balance, balanceBefore);
        }
    }
}
